import React, { useState, useEffect } from 'react';
import { Download, Mail, Github, Linkedin, Code, Database, Cloud, ChevronDown } from 'lucide-react';

const Hero = () => {
  const [currentRole, setCurrentRole] = useState(0);

  const roles = [
    { title: "Full-Stack Developer", icon: <Code size={20} />, color: "from-blue-500 to-blue-600" },
    { title: "Data Analyst", icon: <Database size={20} />, color: "from-green-500 to-green-600" },
    { title: "IT Officer", icon: <Cloud size={20} />, color: "from-purple-500 to-purple-600" }
  ];

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentRole((prev) => (prev + 1) % roles.length);
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  return (
    <section className="min-h-screen bg-gradient-to-br from-gray-50 to-blue-50 relative overflow-hidden">
      {/* Subtle background elements */}
      <div className="absolute inset-0 overflow-hidden">
        <div className="absolute -top-40 -right-40 w-80 h-80 bg-primary-100 rounded-full mix-blend-multiply filter blur-xl opacity-30 animate-float"></div>
        <div className="absolute -bottom-40 -left-40 w-80 h-80 bg-accent-100 rounded-full mix-blend-multiply filter blur-xl opacity-30 animate-float" style={{animationDelay: '2s'}}></div>
        <div className="absolute top-40 left-40 w-60 h-60 bg-purple-100 rounded-full mix-blend-multiply filter blur-xl opacity-30 animate-float" style={{animationDelay: '4s'}}></div>
      </div>

      <div className="container-max section-padding relative z-10">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center min-h-screen">

          {/* Left Content */}
          <div className="space-y-8 text-center lg:text-left">
            {/* Greeting */}
            <div className="animate-fade-in">
              <div className="inline-flex items-center gap-2 px-4 py-2 bg-white rounded-full shadow-sm border border-gray-200 text-gray-600 text-sm font-medium mb-6">
                <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
                Available for opportunities
              </div>
            </div>

            {/* Main Heading */}
            <div className="animate-slide-up" style={{animationDelay: '0.2s'}}>
              <h1 className="text-5xl md:text-6xl lg:text-7xl font-bold text-gray-900 mb-6 font-poppins leading-tight">
                Samuel
                <br />
                <span className="gradient-text">Alemayehu</span>
              </h1>
            </div>

            {/* Dynamic Role Display */}
            <div className="animate-slide-up" style={{animationDelay: '0.4s'}}>
              <div className="flex items-center gap-3 justify-center lg:justify-start mb-6">
                <div className={`w-10 h-10 rounded-lg bg-gradient-to-r ${roles[currentRole].color} flex items-center justify-center text-white transition-all duration-500 shadow-lg`}>
                  {roles[currentRole].icon}
                </div>
                <div className="text-left">
                  <p className="text-gray-500 text-sm font-medium">Currently</p>
                  <h2 className="text-xl md:text-2xl font-semibold text-gray-900 transition-all duration-500">
                    {roles[currentRole].title}
                  </h2>
                </div>
              </div>
            </div>

            {/* Description */}
            <div className="animate-slide-up" style={{animationDelay: '0.6s'}}>
              <p className="text-lg text-gray-700 leading-relaxed max-w-2xl mx-auto lg:mx-0">
                Passionate about leveraging technology to solve complex problems and drive innovation. 
                With expertise spanning full-stack development, data analysis, and IT operations, 
                I create digital solutions that make a meaningful impact.
              </p>
            </div>

            {/* Action Buttons */}
            <div className="flex flex-col sm:flex-row gap-4 justify-center lg:justify-start animate-slide-up" style={{animationDelay: '0.8s'}}>
